(15,1,'2026-08-07 01:45:42','2026-08-07 01:45:42','<!-- wp:nntm/feature-carousel {\"slides\":[{\"imageId\":424,\"imageUrl\":\"http://nntm.com/wp-content/uploads/2026/08/babe09526ac0ea8353f0d599855314a917cb275e.png\",\"imageAlt\":\"\",\"heading\":\"Tiêu đề banner\",\"text\":\"Lorem ipsum dolor sit amet, consectetur adipiscing elit. Suspendisse sit amet nibh aliquet\",\"ctaLabel\":\"\",\"ctaUrl\":\"\"},{\"imageId\":183,\"imageUrl\":\"http://nntm.com/wp-content/uploads/2026/08/thuyet-phap-bo-de.webp\",\"imageAlt\":\"\",\"heading\":\"Tiêu đề banner\",\"text\":\"Lorem ipsum dolor sit amet, consectetur adipiscing elit. Suspendisse sit amet nibh aliquet\",\"ctaLabel\":\"\",\"ctaUrl\":\"\"},{\"imageId\":181,\"imageUrl\":\"http://nntm.com/wp-content/uploads/2026/08/thap-den-tam.webp\",\"imageAlt\":\"\",\"heading\":\"Tiêu đề banner\",\"text\":\"Lorem ipsum dolor sit amet, consectetur adipiscing elit. Suspendisse sit amet nibh aliquet\",\"ctaLabel\":\"\",\"ctaUrl\":\"\"},{\"imageId\":183,\"imageUrl\":\"http://nntm.com/wp-content/uploads/2026/08/thuyet-phap-bo-de.webp\",\"imageAlt\":\"\",\"heading\":\"Tiêu đề banner\",\"text\":\"Lorem ipsum dolor sit amet, consectetur adipiscing elit. Suspendisse sit amet nibh aliquet\",\"ctaLabel\":\"\",\"ctaUrl\":\"\"},{\"imageId\":180,\"imageUrl\":\"http://nntm.com/wp-content/uploads/2026/08/phat-thuyet-phap.webp\",\"imageAlt\":\"\",\"heading\":\"Tiêu đề banner\",\"text\":\"Lorem ipsum dolor sit amet, consectetur adipiscing elit. Suspendisse sit amet nibh aliquet\",\"ctaLabel\":\"\",\"ctaUrl\":\"\"}]} /-->\n\n<!-- wp:nntm/dieu-thuong {\"bannerImages\":[{\"imageId\":178,\"imageUrl\":\"http://nntm.com/wp-content/uploads/2026/08/banner-nui-tu-vien.webp\",\"imageAlt\":\"\"},{\"imageId\":399,\"imageUrl\":\"http://nntm.com/wp-content/uploads/2026/08/fa2ccf933de9e15856b35541ce0ecc12f96310a7.png\",\"imageAlt\":\"\"}],\"bannerImageId\":178,\"bannerImageUrl\":\"http://nntm.com/wp-content/uploads/2026/08/banner-nui-tu-vien.webp\",\"portraitImageId\":179,\"portraitImageUrl\":\"http://nntm.com/wp-content/uploads/2026/08/chan-dung-thien.webp\",\"storyHeading\":\"Hành Trình Tỉnh Thức\",\"storyTextTop\":\"Giữa nhịp sống vô thường, mỗi phút giây quay về soi sáng chính mình là một bước trên con đường tỉnh thức. Sự thực tập được nuôi dưỡng bằng lòng từ bi, sự kiên nhẫn và cái thấy sâu sắc.\",\"gallery\":[{\"imageId\":182,\"imageUrl\":\"http://nntm.com/wp-content/uploads/2026/08/thuong-nguoi.webp\",\"imageAlt\":\"Thuong Nguoi\"},{\"imageId\":183,\"imageUrl\":\"http://nntm.com/wp-content/uploads/2026/08/thuyet-phap-bo-de.webp\",\"imageAlt\":\"Thuyet Phap Bo De\"},{\"imageId\":180,\"imageUrl\":\"http://nntm.com/wp-content/uploads/2026/08/phat-thuyet-phap.webp\",\"imageAlt\":\"Phat Thuyet Phap\"}],\"storyTextBottom\":\"Từ những lời dạy mộc mạc đến từng việc làm chân thành, con đường ấy được tiếp nối trong đời sống hằng ngày — nơi mỗi người tự thắp lên ánh sáng bình an cho mình và cho người.\",\"ctaUrl\":\"http://nntm.com/bai-viet/vi-sao-tam-an-tinh-giua-doi-nhieu-bien-dong-lai-chinh-la-canh-cua-dau-tien-buoc-vao-con-duong-tu-tap-chan-that-cua-nguoi-con-phat/\",\"slides\":[{\"imageId\":184,\"imageUrl\":\"http://nntm.com/wp-content/uploads/2026/08/tong-chi-dia-tang.webp\",\"imageAlt\":\"Tong Chi Dia Tang\",\"heading\":\"Hạnh Nguyện Địa Tạng\",\"text\":\"Phát tâm rộng lớn, lấy lợi lạc chúng sinh làm con đường tu học.\"},{\"imageId\":181,\"imageUrl\":\"http://nntm.com/wp-content/uploads/2026/08/thap-den-tam.webp\",\"imageAlt\":\"Thap Den Tam\",\"heading\":\"Thắp Đèn Tâm\",\"text\":\"Một niệm sáng trong có thể soi rọi cả hành trình trở về.\"},{\"imageId\":182,\"imageUrl\":\"http://nntm.com/wp-content/uploads/2026/08/thuong-nguoi.webp\",\"imageAlt\":\"Thuong Nguoi\",\"heading\":\"Lắng Nghe Bằng Từ Bi\",\"text\":\"Từ bi bắt đầu khi ta thật sự có mặt và lắng nghe.\"},{\"imageId\":183,\"imageUrl\":\"http://nntm.com/wp-content/uploads/2026/08/thuyet-phap-bo-de.webp\",\"imageAlt\":\"Thuyet Phap Bo De\",\"heading\":\"Nương Dưới Cội Bồ Đ