(172,0,'2026-08-13 07:51:16','2026-08-13 07:51:16','<!-- wp:nntm/hero-slider {\"slides\":[{\"imageId\":114,\"imageUrl\":\"http://nntm.com/wp-content/uploads/2026/08/b60a51a7fa231a1fbdd9cc8cad6c1840694d5a9c.jpg\",\"imageAlt\":\"\",\"heading\":\"Từ bi trong hành động, tĩnh lặng trong tâm hồn.\",\"text\":\"Thực hành yêu thương bằng trí tuệ, nuôi dưỡng bình an từ nội tâm.\",\"ctaLabel\":\"Xem thêm\",\"ctaUrl\":\"http://nntm.com/?nntm_section=phap-toa\"},{\"imageId\":115,\"imageUrl\":\"http://nntm.com/wp-content/uploads/2026/08/cd9b5cfc10741f974187c1f4ebee75f7bc037e23.jpg\",\"imageAlt\":\"\",\"heading\":\"Mỗi bước chân là một lần trở về.\",\"text\":\"Chánh niệm không ở đâu xa, nó nằm trong hơi thở kế tiếp.\",\"ctaLabel\":\"Xem thêm\",\"ctaUrl\":\"http://nntm.com/?nntm_section=phap-toa\"},{\"imageId\":89,\"imageUrl\":\"http://nntm.com/wp-content/uploads/2026/08/hero-3.png\",\"imageAlt\":\"\",\"heading\":\"Nghe được tiếng lòng mình, mới nghe được tiếng đời.\",\"text\":\"Tĩnh lặng là nơi trí tuệ bắt đầu lên tiếng.\",\"ctaLabel\":\"Xem thêm\",\"ctaUrl\":\"http://nntm.com/?nntm_section=phap-toa\"}],\"autoplay\":true,\"interval\":6,\"sideCardCtaLabel\":\"Xem thêm\",\"quickLinksParentTermId\":3,\"sideCardEnabled\":true,\"sideCardPostType\":\"nntm_article\",\"sideCardTaxonomy\":\"nntm_section\",\"sideCardTermId\":5} /-->\n\n<!-- wp:nntm/article-mosaic {\"heading\":\"\",\"postType\":\"nntm_article\",\"taxonomy\":\"nntm_section\",\"termId\":5,\"leadMedia\":\"tall\",\"orderBy\":\"newest\",\"showDate\":false,\"showCategory\":false,\"viewAllLabel\":\"Xem Tất cả\",\"viewAllUrl\":\"http://nntm.com/phan-muc/hoa-khai/\"} /--><!-- wp:nntm/article-feature {\"postId\":0,\"postType\":\"nntm_article\",\"taxonomy\":\"nntm_section\",\"termId\":5,\"maxParagraphs\":8,\"ctaLabel\":\"Xem thêm\",\"mediaPosition\":\"right\"} /-->\n\n<!-- wp:nntm/card-list {\"heading\":\"Xuyên Vạn Kiếp\",\"subheading\":\"\",\"postType\":\"nntm_video\",\"taxonomy\":\"nntm_series\",\"termId\":20,\"variant\":\"video\",\"