(409,1,'2026-08-15 05:57:35','2026-08-15 05:57:35','<!-- wp:nntm/card-list {\"heading\":\"Chuyện Về Thầy Tôi\",\"postType\":\"nntm_retreat\",\"taxonomy\":\"nntm_topic\",\"termId\":16,\"variant\":\"khoa-tu\",\"showViewAll\":true,\"layout\":\"carousel\",\"showDate\":false,\"showCategory\":false,\"className\":\"nntm-lien-dan-khoa\"} /-->\n\n<!-- wp:nntm/card-list {\"heading\":\"Chuyện Tăng Thân\",\"postType\":\"nntm_retreat\",\"taxonomy\":\"nntm_topic\",\"termId\":17,\"variant\":\"khoa-tu\",\"postsPerPage\":5,\"layout\":\"carousel\",\"showDate\":false,\"showCategory\":false,\"className\":\"nntm-lien-dan-lich\"} /-->\n\n<!-- wp:nntm/dieu-thuong {\"heading\":\"Hư Không và Vỏ Ốc\",\"introTitle\":\"\",\"introText\":\"\",\"slides\":[{\"imageId\":184,\"imageUrl\":\"http://nntm.com/wp-content/uploads/2026/08/tong-chi-dia-tang.webp\",\"imageAlt\":\"Tong Chi Dia Tang\",\"heading\":\"Album Tác phẩm của các Chú Tiểu \\u0026 Tiểu Ni\",\"text\":\"Phát tâm rộng lớn, lấy lợi lạc chúng sinh làm con đường tu học.\"},{\"imageId\":181,\"imageUrl\":\"http://nntm.com/wp-content/uploads/2026/08/thap-den-tam.webp\",\"imageAlt\":\"Thap Den Tam\",\"heading\":\"Thắp Đèn Tâm\",\"text\":\"Một niệm sáng trong có thể soi rọi cả hành trình trở về.\"},{\"imageId\":182,\"imageUrl\":\"http://nntm.com/wp-content/uploads/2026/08/thuong-nguoi.webp\",\"imageAlt\":\"Thuong Nguoi\",\"heading\":\"Lắng Nghe Bằng Từ Bi\",\"text\":\"Từ bi bắt đầu khi ta thật sự có mặt và lắng nghe.\"},{\"imageId\":183,\"imageUrl\":\"http://nntm.com/wp-content/uploads/2026/08/thuyet-phap-bo-de.webp\",\"imageAlt\":\"Thuyet Phap Bo De\",\"heading\":\"Nương Dưới Cội Bồ Đề\",\"text\":\"Giới, định và tuệ là nền đất vững chắc của người học đạo.\"},{\"imageId\":180,\"imageUrl\":\"http://nntm.com/wp-content/uploads/2026/08/phat-thuyet-phap.webp\",\"imageAlt\":\"Phat Thuyet Phap\",\"heading\":\"Con Đường Tỉnh Thức\",\"text\":\"Mỗi bước chân tỉnh thức đều đưa ta trở về với chính mình.\"}],\"bannerImageId\":178,\"bannerImageUrl\":\"http://nntm.com/wp-content/uploads/2026/08/banner-nui-tu-vien.webp\",\"portraitImageId\":179,\"portraitImageUrl\":\"http://nntm.com/wp-content/uploads/2026/08/chan-dung-thien.webp\",\"storyTextTop\":\"Giữa nhịp sống vô thường, mỗi phút giây quay về soi sáng chính mình là một bước trên con đường tỉnh thức. Sự thực tập được nuôi dưỡng bằng lòng từ bi, sự kiên nhẫn và cái thấy sâu sắc.\",\"gallery\":[{\"imageId\":182,\"imageUrl\":\"http://nntm.com/wp-content/uploads/2026/08/thuong-nguoi.webp\",\"imageAlt\":\"Thuong Nguoi\"},{\"imageId\":183,\"imageUrl\":\"http://nntm.com/wp-content/uploads/2026/08/thuyet-phap-bo-de.webp\",\"imageAlt\":\"Thuyet Phap Bo De\"},{\"imageId\":180,\"imageUrl\":\"http://nntm.com/wp-content/uploads/2026/08/phat-thuyet-phap.webp\",\"imageAlt\":\"Phat Thuyet Phap\"}],\"storyTextBottom\":\"Từ những lời dạy mộc mạc đến từng việc làm chân thành, con đường ấy được tiếp nối trong đời sống hằng ngày — nơi mỗi người tự thắp lên ánh sáng bình an cho mình và cho người.\",\"ctaUrl\":\"http://nntm.com/bai-viet/vi-sao-tam-an-tinh-giua-doi-nhieu-bien-dong-lai-chinh-la-canh-cua-dau-tien-buoc-vao-con-duong-tu-tap-chan-that-cua-nguoi-con-phat/\"} /-->\n\n<!-- wp:nntm/article-mosaic {\"heading\":\"\\u003cbr\\u003eBóng Trăng Rừng Xưa\",\"postType\":\"nntm_article\",\"taxonomy\":\"nntm_section\",\"termId\":5,\"showCategory\":false,\"viewAllLabel\":\"Xem Tất cả\",\"viewAllUrl\":\"http://nntm.com/phan-muc/hoa-khai/\",\"showDate\":false} /-->','Vườn Xoài','','inherit','closed','closed','','77-revision-v1','','','2026-08-15 05:57:35','2026-08-15 05:57:35','',77,'http://nntm.com/?p=409',0,'revision','',0),
