(411,1,'2026-08-15 06:10:57','2026-08-15 06:10:57','<!-- wp:nntm/hero-slider {\"slides\":[{\"imageId\":114,\"imageUrl\":\"http://nntm.com/wp-content/uploads/2026/08/b60a51a7fa231a1fbdd9cc8cad6c1840694d5a9c.jpg\",\"imageAlt\":\"\",\"heading\":\"Từ bi trong hành động, tĩnh lặng trong tâm hồn.\",\"text\":\"Thực hành yêu thương bằng trí tuệ, nuôi dưỡng bình an từ nội tâm.\",\"ctaLabel\":\"Xem thêm\",\"ctaUrl\":\"http://nntm.com/?nntm_section=phap-toa\"},{\"imageId\":115,\"imageUrl\":\"http://nntm.com/wp-content/uploads/2026/08/cd9b5cfc10741f974187c1f4ebee75f7bc037e23.jpg\",\"imageAlt\":\"\",\"heading\":\"Mỗi bước chân là một lần trở về.\",\"text\":\"Chánh niệm không ở đâu xa, nó nằm trong hơi thở kế tiếp.\",\"ctaLabel\":\"Xem thêm\",\"ctaUrl\":\"http://nntm.com/?nntm_section=phap-toa\"},{\"imageId\":89,\"imageUrl\":\"http://nntm.com/wp-content/uploads/2026/08/hero-3.png\",\"imageAlt\":\"\",\"heading\":\"Nghe được tiếng lòng mình, mới nghe được tiếng đời.\",\"text\":\"Tĩnh lặng là nơi trí tuệ bắt đầu lên tiếng.\",\"ctaLabel\":\"Xem thêm\",\"ctaUrl\":\"http://nntm.com/?nntm_section=phap-toa\"}],\"sideCardTermId\":5,\"quickLinksParentTermId\":3} /-->\n\n<!-- wp:nntm/article-mosaic {\"heading\":\"\",\"postType\":\"nntm_article\",\"taxonomy\":\"nntm_section\",\"termId\":5,\"showCategory\":false,\"viewAllLabel\":\"Xem Tất cả\",\"viewAllUrl\":\"http://nntm.com/phan-muc/hoa-khai/\",\"showDate\":false} /-->\n\n<!-- wp:nntm/article-feature {\"postType\":\"nntm_article\",\"taxonomy\":\"nntm_section\",\"termId\":5,\"ctaLabel\":\"Xem thêm\"} /-->\n\n<!-- wp:nntm/card-list {\"heading\":\"Xuyên Vạn Kiếp\",\"postType\":\"nntm_video\",\"taxonomy\":\"nntm_series\",\"termId\":20,\"variant\":\"video\",\"layout\":\"carousel\",\"background\":\"toi\",\"showDate\":false,\"showCategory\":false,\"headingAbove\":\"Gót Son\",\"captionBelow\":\"Mọi câu chuyện đều là người thật, việc thật, được chúng tôi khảo sát và phỏng vấn trực tiếp. Có những điều vượt ngoài suy luận thế trí biện thông, nhờ vậy c